import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"24、【复】 震下坤上","description":"温公易说 - 24、【复】 震下坤上","frontmatter":{"title":"24、【复】 震下坤上","description":"温公易说 - 24、【复】 震下坤上"},"headers":[],"relativePath":"zh/classics/wengong/025.md","filePath":"zh/classics/wengong/025.md"}'),n={name:"zh/classics/wengong/025.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_24、【复】-震下坤上" tabindex="-1">24、【复】 震下坤上 <a class="header-anchor" href="#_24、【复】-震下坤上" aria-label="Permalink to “24、【复】 震下坤上”">​</a></h1><h3 id="彖曰-复-亨。刚反动而以顺行-是以出入无疾-朋来无咎。反复其道-七日来复-天行也。利有攸往-刚长也。复其见天地之心乎" tabindex="-1">彖曰：复，亨。刚反动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复其见天地之心乎？ <a class="header-anchor" href="#彖曰-复-亨。刚反动而以顺行-是以出入无疾-朋来无咎。反复其道-七日来复-天行也。利有攸往-刚长也。复其见天地之心乎" aria-label="Permalink to “彖曰：复，亨。刚反动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复其见天地之心乎？”">​</a></h3><p>七日来复何也？冬至卦气起于中孚，次复，次屯，次谦，次睽。凡一卦御六日，二百四十分日之二十一，五卦合三十日，二百四十分日之一百五。此冬至距大寒之数也，故入冬至，凡涉七日而复之气应也。</p><h3 id="象曰-雷在地中-复。先王以至日闭关-商旅不行-后不省方。" tabindex="-1">象曰：雷在地中，复。先王以至日闭关，商旅不行，后不省方。 <a class="header-anchor" href="#象曰-雷在地中-复。先王以至日闭关-商旅不行-后不省方。" aria-label="Permalink to “象曰：雷在地中，复。先王以至日闭关，商旅不行，后不省方。”">​</a></h3><h3 id="初九-不远复-无祗悔-元吉-象曰-不远之复-以修身也。" tabindex="-1">初九：不远复，无祗悔，元吉 象曰：不远之复，以修身也。 <a class="header-anchor" href="#初九-不远复-无祗悔-元吉-象曰-不远之复-以修身也。" aria-label="Permalink to “初九：不远复，无祗悔，元吉 象曰：不远之复，以修身也。”">​</a></h3><h3 id="六二-休复-吉-象曰-休复之吉-以下仁也。" tabindex="-1">六二：休复，吉 象曰：休复之吉，以下仁也。 <a class="header-anchor" href="#六二-休复-吉-象曰-休复之吉-以下仁也。" aria-label="Permalink to “六二：休复，吉 象曰：休复之吉，以下仁也。”">​</a></h3><h3 id="六三-频复-厉-无咎-象曰-频复之厉-义无咎也。" tabindex="-1">六三：频复，厉，无咎 象曰：频复之厉，义无咎也。 <a class="header-anchor" href="#六三-频复-厉-无咎-象曰-频复之厉-义无咎也。" aria-label="Permalink to “六三：频复，厉，无咎 象曰：频复之厉，义无咎也。”">​</a></h3><p>复者，过而能复之谓也。不慎其始，频过而复，亦已危矣。虽然，犹愈于迷而不复也，故曰无咎。</p><h3 id="六四-中行独复-象曰-中行独复-以从道也。" tabindex="-1">六四：中行独复 象曰：中行独复，以从道也。 <a class="header-anchor" href="#六四-中行独复-象曰-中行独复-以从道也。" aria-label="Permalink to “六四：中行独复 象曰：中行独复，以从道也。”">​</a></h3><p>中行者，行于众阴之中也。四行众阴之中，独能履正思顺，下应于阳，不陷溺于群邪，而能自复于善者也。故曰中行独复。孔子曰：不曰坚乎，磨而不磷？不曰白乎，涅而不淄？此之谓也。</p><h3 id="六五-敦复-无悔-象曰-敦复无悔-中以自考也。" tabindex="-1">六五：敦复，无悔 象曰：敦复无悔，中以自考也。 <a class="header-anchor" href="#六五-敦复-无悔-象曰-敦复无悔-中以自考也。" aria-label="Permalink to “六五：敦复，无悔 象曰：敦复无悔，中以自考也。”">​</a></h3><h3 id="上六-迷复-凶-有灾眚。用行师-终有大败-以其国君凶-至于十年不克征-象曰-迷复之凶-反君道也。" tabindex="-1">上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征 象曰：迷复之凶，反君道也。 <a class="header-anchor" href="#上六-迷复-凶-有灾眚。用行师-终有大败-以其国君凶-至于十年不克征-象曰-迷复之凶-反君道也。" aria-label="Permalink to “上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征 象曰：迷复之凶，反君道也。”">​</a></h3>',12)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
